CREATE DATABASE IF NOT EXISTS ecobank_db CHARACTER SET utf8mb4;
USE ecobank_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','officer','user') NOT NULL DEFAULT 'user',balance DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE waste_types(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,price_per_kg DECIMAL(12,2) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1)ENGINE=InnoDB;
CREATE TABLE deposits(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,waste_type_id INT NOT NULL,weight DECIMAL(8,2) NOT NULL,amount DECIMAL(14,2) NOT NULL,status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending',verified_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(waste_type_id) REFERENCES waste_types(id),FOREIGN KEY(verified_by) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type ENUM('deposit','withdrawal') NOT NULL,amount DECIMAL(14,2) NOT NULL,note VARCHAR(150),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE withdrawals(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,amount DECIMAL(14,2) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id))ENGINE=InnoDB;
CREATE TABLE audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
